('p1_int01_learning','learning','Antiderivatives learning','Первообразные: обучение','Boshlang‘ich funksiyalar: o‘rganish'),('p1_int02_learning','learning','Boundary-condition integration learning','Интегрирование с условием точки: обучение','Nuqta sharti bilan integrallash: o‘rganish'),('p1_int03_learning','learning','Definite integrals learning','Определённые интегралы: обучение','Aniq integrallar: o‘rganish'),
('p1_int01_retest','retest','INT-01 delayed retest','INT-01 отложенный ретест','INT-01 kechiktirilgan retest'),('p1_int02_retest','retest','INT-02 delayed retest','INT-02 отложенный ретест','INT-02 kechiktirilgan retest'),('p1_int03_retest','retest','INT-03 delayed retest','INT-03 отложенный ретест','INT-03 kechiktirilgan retest'),
('p1_aw21_int_core_mixed','mixed','P1 AW21-24 Integration core mixed transfer','P1 AW21–24: смешанный перенос основ интегрирования','P1 AW21–24 integrallash mixed transfer'))
insert into private.exam_prep_assessments(content_version_id,assessment_key,assessment_version,component_code,assessment_type,status,title_en,title_ru,title_uz)
